import sys
input = sys.stdin.read

def solve():
    data = input().split()
    n = int(data[0])
    a = list(map(int, data[1:n+1]))
    b = list(map(int, data[n+1:2*n+1]))

    events = [(value, 'A') for value in a] + [(value, 'B') for value in b]
    events.sort(reverse=True, key=lambda x: (x[0], x[1]))

    a_score, b_score = 0, 0
    turn_a = True

    for value, owner in events:
        if turn_a:
            if owner == 'A':
                a_score += value
            else:
                pass  # A can remove from B's list, but doesn't affect score
        else:
            if owner == 'B':
                b_score += value
            else:
                pass  # B can remove from A's list, but doesn't affect score

        turn_a = not turn_a  # Switch turns

    print(a_score - b_score)

solve()

