import sys
input = sys.stdin.read
data = input().split()
n = int(data[0])
a = list(map(int, data[1:n+1]))
b = list(map(int, data[n+1:]))

a.sort(reverse=True)
b.sort(reverse=True)

result = 0
turn = 1
while a or b:
    if turn == 1:
        if not a:
            b.pop(0)
        elif not b or a[0] >= b[0]:
            result += a.pop(0)
        else:
            b.pop(0)
        turn = 2
    else:
        if not b:
            a.pop(0)
        elif not a or b[0] >= a[0]:
            result -= b.pop(0)
        else:
            a.pop(0)
        turn = 1

print(result)

